const COUNTRY_BY_CODE = new Map(COUNTRIES.map(country => [country.code, country]));
const ALIASES = {
  "US": "США Соединённые Штаты Америки United States of America USA America",
  "GB": "Великобритания Соединённое Королевство United Kingdom Britain Great Britain UK Англия",
  "RU": "РФ Российская Федерация Russia Russian Federation",
  "AE": "ОАЭ Объединённые Арабские Эмираты UAE",
  "KR": "Южная Корея Республика Корея South Korea Korea Republic of",
  "KP": "Северная Корея КНДР North Korea DPRK",
  "CZ": "Чехия Czech Republic Czechia",
  "TR": "Турция Turkey Türkiye",
  "CI": "Кот-д’Ивуар Кот д Ивуар Ivory Coast",
  "CD": "ДР Конго Демократическая Республика Конго DRC Congo Kinshasa",
  "CG": "Республика Конго Congo Brazzaville",
  "TW": "Тайвань Taiwan",
  "HK": "Гонконг Hong Kong",
  "MO": "Макао Macao Macau",
  "VN": "Вьетнам Vietnam Viet Nam",
  "LA": "Лаос Laos",
  "SY": "Сирия Syria",
  "IR": "Иран Iran",
  "MD": "Молдова Moldova",
  "PS": "Палестина Palestine",
  "VA": "Ватикан Vatican Holy See",
  "BO": "Боливия Bolivia",
  "VE": "Венесуэла Venezuela",
  "TZ": "Танзания Tanzania",
  "BN": "Бруней Brunei",
  "TL": "Восточный Тимор East Timor Timor Leste",
  "SZ": "Эсватини Swaziland Свазиленд",
  "CV": "Кабо-Верде Cape Verde",
  "MM": "Мьянма Burma Бирма",
  "BY": "Беларусь Белоруссия Belarus",
  "MK": "Северная Македония North Macedonia FYROM",
  "FM": "Микронезия Федеративные Штаты Микронезии Micronesia",
  "BQ": "Бонайре Синт-Эстатиус Саба Bonaire Sint Eustatius Saba",
  "BL": "Сен-Бартелеми Saint Barthelemy St Barthelemy",
  "MF": "Сен-Мартен Saint Martin St Martin"
};
const normalize = value => String(value ?? '').trim().toLocaleLowerCase('ru-RU').replace(/ё/g,'е').normalize('NFKD').replace(/[\u0300-\u036f]/g,'');

/** True only for an exact, uppercase, assigned ISO 3166-1 alpha-2 code. Empty is optional UI state, not a country. */
export function isCountryCode(value) {
  return typeof value === 'string' && /^[A-Z]{2}$/.test(value) && COUNTRY_BY_CODE.has(value);
}

/** Localized label for a canonical code. Unknown or empty values have no label. */
export function countryLabel(code) {
  const country = COUNTRY_BY_CODE.get(code);
  return country ? country.code + ' — ' + country.name : '';
}

/** Search by code, Russian/English name, or a common alias; exact code then prefixes rank first. */
export function searchCountries(query = '', limit = 249) {
  const q = normalize(query);
  const n = Number.isFinite(Number(limit)) ? Math.max(0,Math.floor(Number(limit))) : 249;
  if (!q) return COUNTRIES.slice(0,n);
  return COUNTRIES.map(country => {
    const code = normalize(country.code);
    const names = [normalize(country.name),normalize(country.nameEn)];
    const aliases = normalize(ALIASES[country.code] || '');
    const match = code.includes(q) || names.some(name => name.includes(q)) || aliases.includes(q);
    const aliasTokens = aliases.split(/[^\p{L}\p{N}]+/u);
    const rank = code === q ? 0 : names.some(name => name === q) ? 1 : aliasTokens.includes(q) ? 2 : code.startsWith(q) ? 3 : names.some(name => name.startsWith(q)) ? 4 : aliases.startsWith(q) ? 5 : 6;
    return {country,match,rank};
  }).filter(item=>item.match).sort((a,b)=>a.rank-b.rank || a.country.name.localeCompare(b.country.name,'ru')).slice(0,n).map(item=>item.country);
}
